// The emoji picker the Web SidebarSectionEmojiPicker opens: emoji-picker-react
// 4.19.1 (`showPreview: false`, `height: 360`, `width: min(340, 100vw - 48)`,
// autofocused search, skin-tone swatch in the search row, nine category
// buttons, pinned category labels over an eight-column emoji grid). Data and
// category sprite are generated by tool/gen-emoji-data. The Web package renders
// its own English strings (no locale data), so none of them go through raftText.
import 'text_selection_toolbar.dart';
import 'hover_region.dart';

import 'dart:math' as math;

import 'package:flutter/material.dart';

import 'emoji_data.g.dart';
import 'icons.dart';
import 'text_scaling.dart' show RaftChrome;
import 'theme.dart';

/// One emoji of the picker data: [unified] code points (`1f44b-1f3fb`),
/// search [words] and the five skin-tone [variants] (`1f3fb`..`1f3ff`).
@immutable
class RaftEmojiEntry {
  const RaftEmojiEntry(this.unified, this.words, [this.variants = const []]);
  final String unified, words;
  final List<String> variants;
  String get emoji => raftEmojiFromUnified(unified);
}

/// `1f44b-1f3fb` -> the emoji string.
String raftEmojiFromUnified(String unified) => String.fromCharCodes([
  for (final part in unified.split('-')) int.parse(part, radix: 16),
]);

/// Category keys in picker order and their `epr` names.
const _categoryNames = <String, String>{
  'suggested': 'Frequently Used',
  'smileys_people': 'Smileys & People',
  'animals_nature': 'Animals & Nature',
  'food_drink': 'Food & Drink',
  'travel_places': 'Travel & Places',
  'activities': 'Activities',
  'objects': 'Objects',
  'symbols': 'Symbols',
  'flags': 'Flags',
};

/// SkinTonePicker colours: neutral, light, medium-light, medium, medium-dark, dark.
const _skinTones = <Color>[
  Color(0xffffd93b),
  Color(0xfffadcbc),
  Color(0xffe0bb95),
  Color(0xffbf917d),
  Color(0xff9b643d),
  Color(0xff594539),
];

/// Frequently used emoji (the picker's `suggested` category), newest first.
final List<String> _recentEmoji = [];

class RaftEmojiPicker extends StatefulWidget {
  const RaftEmojiPicker({
    super.key,
    required this.onEmojiClick,
    this.width = 340,
    this.height = 360,
  });
  final ValueChanged<String> onEmojiClick;
  final double width, height;

  @override
  State<RaftEmojiPicker> createState() => _RaftEmojiPickerState();
}

class _RaftEmojiPickerState extends State<RaftEmojiPicker> {
  static const _cell = 40.0, _label = 40.0, _columns = 8;
  final search = TextEditingController();
  final searchFocus = FocusNode();
  final scroll = ScrollController();
  int tone = 0;
  bool tonesOpen = false;
  String active = 'smileys_people';

  @override
  void initState() {
    super.initState();
    search.addListener(() => setState(() {}));
    scroll.addListener(trackActive);
    searchFocus.addListener(() => setState(() {}));
    // `autoFocusSearch: true`.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) searchFocus.requestFocus();
    });
  }

  @override
  void dispose() {
    search.dispose();
    searchFocus.dispose();
    scroll.dispose();
    super.dispose();
  }

  bool get searching => search.text.trim().isNotEmpty;

  /// Categories with the emoji they show (suggested only once something was
  /// picked; search keeps categories that still have a match).
  List<(String, List<RaftEmojiEntry>)> get categories {
    final query = search.text.trim().toLowerCase();
    return [
      if (!searching && _recentEmoji.isNotEmpty)
        (
          'suggested',
          [for (final e in _recentEmoji) RaftEmojiEntry(_unifiedOf(e), '')],
        ),
      for (final entry in raftEmojiByCategory.entries)
        if (!searching)
          (entry.key, entry.value)
        else if (entry.value.where((e) => e.words.contains(query)).isNotEmpty)
          (
            entry.key,
            [
              for (final e in entry.value)
                if (e.words.contains(query)) e,
            ],
          ),
    ];
  }

  static String _unifiedOf(String emoji) =>
      emoji.runes.map((r) => r.toRadixString(16)).join('-');

  double rowsHeight(int count) => (count / _columns).ceil() * _cell;

  void trackActive() {
    var offset = 0.0;
    var current = categories.firstOrNull?.$1 ?? active;
    for (final (key, items) in categories) {
      if (scroll.offset + 1 >= offset) current = key;
      offset += _label + rowsHeight(items.length);
    }
    if (current != active) setState(() => active = current);
  }

  void jumpTo(String key) {
    var offset = 0.0;
    for (final (name, items) in categories) {
      if (name == key) {
        scroll.jumpTo(math.min(offset, scroll.position.maxScrollExtent));
        setState(() => active = key);
        return;
      }
      offset += _label + rowsHeight(items.length);
    }
  }

  void pick(RaftEmojiEntry e) {
    final chosen = tone > 0 && e.variants.length >= tone
        ? raftEmojiFromUnified(e.variants[tone - 1])
        : e.emoji;
    _recentEmoji
      ..remove(chosen)
      ..insert(0, chosen);
    if (_recentEmoji.length > 8)
      _recentEmoji.removeRange(8, _recentEmoji.length);
    widget.onEmojiClick(chosen);
  }

  @override
  Widget build(BuildContext context) {
    final t = RaftTokens.of(context);
    final dark = t.dark;
    final text = dark ? const Color(0xffc0c0c0) : const Color(0xff858585);
    final bg = dark ? const Color(0xff222222) : Colors.white;
    final border = dark ? const Color(0xff151617) : const Color(0xffe7e7e7);
    final inputBg = dark ? const Color(0xff333333) : const Color(0xfff6f6f6);
    final inputActiveBg = dark ? Colors.black : inputBg;
    final highlight = dark ? const Color(0xffc0c0c0) : const Color(0xff007aeb);
    final hover = dark ? const Color(0xf6363636) : const Color(0xffe5f0fa);
    final labelBg = dark ? const Color(0xe6222222) : const Color(0xe6ffffff);
    final focused = searchFocus.hasFocus;
    final cats = categories;
    final inner = widget.width - 2;
    final cellWidth = (inner - 20) / _columns;
    TextStyle sans(double size, Color color, {FontWeight? weight}) => TextStyle(
      fontFamily: 'sans-serif',
      fontSize: size,
      height: 1.15,
      color: color,
      fontWeight: weight,
      decoration: TextDecoration.none,
    );
    return Material(
      type: MaterialType.transparency,
      child: Container(
        width: widget.width,
        height: widget.height,
        decoration: BoxDecoration(
          color: bg,
          border: Border.all(color: border),
          borderRadius: BorderRadius.circular(8),
        ),
        clipBehavior: Clip.antiAlias,
        child: Column(
          children: [
            // Header: `padding: 15px 10px`; the search box fills the row and the
            // 28px skin tone picker sits at its end (expanding leftwards over it).
            Padding(
              // ds-allow: Web emoji-picker-react.js --epr-header-padding `15px 10px`
              padding: const EdgeInsets.fromLTRB(10, 15, 10, 15),
              child: SizedBox(
                height: 40,
                child: Stack(
                  alignment: Alignment.centerLeft,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Container(
                            height: 40,
                            decoration: BoxDecoration(
                              color: focused ? inputActiveBg : inputBg,
                              border: Border.all(
                                color: focused ? highlight : inputBg,
                              ),
                              borderRadius: BorderRadius.circular(8),
                            ),
                            padding: const EdgeInsets.symmetric(horizontal: 30),
                            alignment: Alignment.centerLeft,
                            child: Stack(
                              clipBehavior: Clip.none,
                              alignment: Alignment.centerLeft,
                              children: [
                                TextField(
                                  contextMenuBuilder:
                                      RaftTextSelectionToolbar.editableText,
                                  key: const ValueKey('emoji-picker-search'),
                                  controller: search,
                                  focusNode: searchFocus,
                                  autofocus: true,
                                  style: sans(16, text),
                                  cursorColor: highlight,
                                  decoration: InputDecoration(
                                    isCollapsed: true,
                                    contentPadding: EdgeInsets.zero,
                                    filled: false,
                                    border: InputBorder.none,
                                    enabledBorder: InputBorder.none,
                                    focusedBorder: InputBorder.none,
                                    hintText: 'Search',
                                    hintStyle: sans(16, text),
                                  ),
                                ),
                                Positioned(
                                  left: -17,
                                  child: IgnorePointer(
                                    child: RaftIcon(
                                      RaftGlyph.search,
                                      size: 14,
                                      color: text,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                        _Swatch(
                          key: const ValueKey('emoji-tone-button'),
                          color: _skinTones[tone],
                          selected: false,
                          onTap: () => setState(() => tonesOpen = true),
                        ),
                      ],
                    ),
                    if (tonesOpen)
                      Positioned(
                        right: 0,
                        child: Container(
                          decoration: BoxDecoration(
                            color: bg,
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Row(
                            children: [
                              for (var i = 0; i < _skinTones.length; i++)
                                _Swatch(
                                  key: ValueKey('emoji-tone-$i'),
                                  color: _skinTones[i],
                                  selected: i == tone,
                                  onTap: () => setState(() {
                                    tone = i;
                                    tonesOpen = false;
                                  }),
                                ),
                            ],
                          ),
                        ),
                      ),
                  ],
                ),
              ),
            ),
            // CategoryNavigation (`padding: 15px 10px`, 30px buttons); dimmed and
            // inert while a query is typed.
            Opacity(
              opacity: searching ? .3 : 1,
              child: IgnorePointer(
                ignoring: searching,
                child: Padding(
                  // ds-allow: Web emoji-picker-react.js category navigation `padding: 15px 10px`
                  padding: const EdgeInsets.fromLTRB(10, 15, 10, 15),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceAround,
                    children: [
                      for (final key in _categoryNames.keys)
                        _NavButton(
                          category: key,
                          active: key == active && !searching,
                          dark: dark,
                          // ignore: raft_lints/avoid_render_index_assertion -- Static category-name map covering every category key of the generated emoji data.
                          label: _categoryNames[key]!,
                          onTap: () => jumpTo(key),
                        ),
                    ],
                  ),
                ),
              ),
            ),
            Expanded(
              child: cats.isEmpty
                  ? Center(
                      child: Text('No results found', style: sans(16, text)),
                    )
                  : CustomScrollView(
                      controller: scroll,
                      slivers: [
                        for (final (key, items) in cats) ...[
                          SliverPersistentHeader(
                            pinned: true,
                            delegate: _LabelDelegate(
                              // ignore: raft_lints/avoid_render_index_assertion -- Static category-name map covering every category key of the generated emoji data.
                              label: _categoryNames[key]!,
                              background: labelBg,
                              style: sans(16, text, weight: FontWeight.w700),
                            ),
                          ),
                          SliverPadding(
                            padding: const EdgeInsets.symmetric(horizontal: 10),
                            sliver: SliverGrid.builder(
                              gridDelegate:
                                  SliverGridDelegateWithFixedCrossAxisCount(
                                    crossAxisCount: _columns,
                                    mainAxisExtent: _cell,
                                  ),
                              itemCount: items.length,
                              itemBuilder: (context, i) => _EmojiCell(
                                entry: items[i],
                                tone: tone,
                                hover: hover,
                                width: cellWidth,
                                onTap: () => pick(items[i]),
                              ),
                            ),
                          ),
                        ],
                      ],
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

class _LabelDelegate extends SliverPersistentHeaderDelegate {
  const _LabelDelegate({
    required this.label,
    required this.background,
    required this.style,
  });
  final String label;
  final Color background;
  final TextStyle style;
  @override
  double get minExtent => 40;
  @override
  double get maxExtent => 40;
  @override
  Widget build(BuildContext context, double shrinkOffset, bool overlaps) =>
      Container(
        color: background,
        padding: const EdgeInsets.symmetric(horizontal: 10),
        alignment: Alignment.centerLeft,
        child: Text(label, style: style),
      );
  @override
  bool shouldRebuild(_LabelDelegate old) =>
      old.label != label || old.background != background || old.style != style;
}

class _EmojiCell extends StatefulWidget {
  const _EmojiCell({
    required this.entry,
    required this.tone,
    required this.hover,
    required this.width,
    required this.onTap,
  });
  final RaftEmojiEntry entry;
  final int tone;
  final Color hover;
  final double width;
  final VoidCallback onTap;
  @override
  State<_EmojiCell> createState() => _EmojiCellState();
}

class _EmojiCellState extends State<_EmojiCell> {
  bool hovered = false;
  @override
  Widget build(BuildContext context) {
    final e = widget.entry;
    final shown = widget.tone > 0 && e.variants.length >= widget.tone
        ? raftEmojiFromUnified(e.variants[widget.tone - 1])
        : e.emoji;
    return Semantics(
      button: true,
      label: e.words.isEmpty ? shown : e.words,
      excludeSemantics: true,
      child: RaftHoverRegion(
        cursor: SystemMouseCursors.click,
        onEnter: (_) => setState(() => hovered = true),
        onExit: (_) => setState(() => hovered = false),
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: widget.onTap,
          child: Center(
            // ignore: raft_lints/avoid_fixed_height_text -- a fixed 40px emoji cell: the glyph is bounded by RaftChrome and always fits
            child: Container(
              width: 40,
              height: 40,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: hovered ? widget.hover : null,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                shown,
                // A glyph in a fixed 40px cell: it grows with the text size
                // only up to the chrome bound.
                textScaler: RaftChrome.boundedScalerOf(context),
                style: const TextStyle(
                  fontSize: 25,
                  height: 1,
                  decoration: TextDecoration.none,
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _NavButton extends StatefulWidget {
  const _NavButton({
    required this.category,
    required this.active,
    required this.dark,
    required this.label,
    required this.onTap,
  });
  final String category, label;
  final bool active, dark;
  final VoidCallback onTap;
  @override
  State<_NavButton> createState() => _NavButtonState();
}

class _NavButtonState extends State<_NavButton> {
  bool hovered = false;
  @override
  Widget build(BuildContext context) {
    final lit = widget.active || hovered;
    final state = widget.dark
        ? (lit ? 'darkActive' : 'darkNormal')
        : (lit ? 'active' : 'normal');
    return Semantics(
      button: true,
      selected: widget.active,
      label: widget.label,
      excludeSemantics: true,
      child: RaftHoverRegion(
        cursor: SystemMouseCursors.click,
        onEnter: (_) => setState(() => hovered = true),
        onExit: (_) => setState(() => hovered = false),
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: widget.onTap,
          child: RaftEmojiNavIcon(widget.category, state: state),
        ),
      ),
    );
  }
}

class _Swatch extends StatelessWidget {
  const _Swatch({
    super.key,
    required this.color,
    required this.selected,
    required this.onTap,
  });
  final Color color;
  final bool selected;
  final VoidCallback onTap;
  @override
  Widget build(BuildContext context) {
    final dark = RaftTokens.of(context).dark;
    // `--epr-skin-tone-outer-border-color` ring, then the picker background
    // (`inner-border`), then the tone.
    final outer = selected
        ? const Color(0xff007aeb)
        : (dark ? const Color(0xffaaaaaa) : const Color(0xff555555));
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: SizedBox.square(
        dimension: 28,
        child: Center(
          child: Container(
            width: 16,
            height: 16,
            // ds-allow: Web emoji-picker-react.js .epr-tone `box-shadow: inset 0 0 0 1px`
            padding: const EdgeInsets.all(1),
            decoration: BoxDecoration(
              color: dark ? const Color(0xff222222) : Colors.white,
              border: Border.all(color: outer),
              borderRadius: BorderRadius.circular(5),
            ),
            child: DecoratedBox(
              decoration: BoxDecoration(
                color: color,
                borderRadius: BorderRadius.circular(3),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
